# Regenerates templates/index.json with the approved wireframe copy for every converted Homepage section (so a fresh theme renders the approved page).
# Add each section here as it is converted. Order = page order.
$T = Split-Path -Parent $PSScriptRoot; $utf8 = New-Object Text.UTF8Encoding($false)
function Blk($pairs) { $b = [ordered]@{}; $o = @(); $i = 0; foreach ($pr in $pairs) { $i++; $id = "b$i"; $b[$id] = [ordered]@{ type = $pr[0]; settings = $pr[1] }; $o += $id }; @{ blocks = $b; block_order = $o } }
function Sec($type, $settings, $blk) { $x = [ordered]@{ type = $type; settings = $settings }; if ($blk) { $x['blocks'] = $blk.blocks; $x['block_order'] = $blk.block_order }; $x }
$S = [ordered]@{}
$S['hero'] = Sec 'hero-banner' ([ordered]@{ height = 'large'; eyebrow = 'The ritual edit · AW26'; heading = 'Radiance, <em>Gently</em> Nudged.'; text = 'Skin care, makeup, hair and body, chosen to work together.'; button_label = 'Shop the edit'; button_link = '#s06'; button_2_label = 'Find your routine'; button_2_link = '#s07'; featured_label = 'Featured'; featured_title = 'Face Serum'; featured_meta = '30 ml · $32.00'; featured_url = '#s06'; anchor = 's03' }) $null
$S['usp'] = Sec 'usp-row' ([ordered]@{ anchor = 's04' }) (Blk @( @('usp_item', [ordered]@{ icon = 'heart'; title = 'Cruelty-free'; text = 'Only if certified or verifiable' }), @('usp_item', [ordered]@{ icon = 'check-circle'; title = 'Clean'; text = 'Define what clean means for the range' }), @('usp_item', [ordered]@{ icon = 'location'; title = 'Free shipping'; text = 'On orders over $50' }), @('usp_item', [ordered]@{ icon = 'arrow-left'; title = 'Easy returns'; text = 'Return within 30 days' }) ))
$S['categories'] = Sec 'category-grid' ([ordered]@{ heading = 'Shop by category'; anchor = 's05' }) (Blk @( @('category_card', [ordered]@{ layout = 'tall'; title = 'Skin care'; subtitle = 'Cleansers, serums and moisturisers'; link_text = 'Shop skin care'; link = '#' }), @('category_card', [ordered]@{ layout = 'top_middle'; title = 'Makeup'; subtitle = 'Face, eyes and lips'; link_text = 'Shop makeup'; link = '#' }), @('category_card', [ordered]@{ layout = 'top_right'; title = 'Hair'; subtitle = 'Shampoo, conditioner and styling'; link_text = 'Shop hair'; link = '#' }), @('category_card', [ordered]@{ layout = 'wide'; title = 'Body'; subtitle = 'Wash, lotion and body care'; link_text = 'Shop body'; link = '#' }) ))
$S['featured'] = Sec 'featured-collection' ([ordered]@{ heading = 'Shop our favourites'; products_to_show = 4; button_label = 'View all best sellers'; button_link = '#'; anchor = 's06' }) (Blk @( @('tab', [ordered]@{ label = 'Best sellers'; collection = 'best-sellers' }), @('tab', [ordered]@{ label = 'New launches'; collection = 'new-launches' }), @('tab', [ordered]@{ label = 'Sets' }) ))
$S['concern'] = Sec 'concern-routine' ([ordered]@{ heading = 'Shop by concern or routine'; lead = 'Start with what you want to look after, or build a routine step by step.'; concern_title = 'By skin concern'; routine_title = 'By routine step'; anchor = 's07' }) (Blk @(
  @('concern', [ordered]@{ title = 'Dryness'; link = '#'; tone = 't2' }), @('concern', [ordered]@{ title = 'Dullness'; link = '#'; tone = 't3' }), @('concern', [ordered]@{ title = 'Breakouts'; link = '#'; tone = 't4' }),
  @('concern', [ordered]@{ title = 'Sensitivity'; link = '#'; tone = '' }), @('concern', [ordered]@{ title = 'Uneven tone'; link = '#'; tone = 't2' }), @('concern', [ordered]@{ title = 'Texture'; link = '#'; tone = 't3' }),
  @('routine_step', [ordered]@{ label = 'Cleanse'; link = '#' }), @('routine_step', [ordered]@{ label = 'Treat'; link = '#' }), @('routine_step', [ordered]@{ label = 'Moisturise'; link = '#' }), @('routine_step', [ordered]@{ label = 'Protect'; link = '#' }) ))
$S['finder'] = Sec 'guided-finder' ([ordered]@{ eyebrow = 'Guided finder'; heading = 'Not sure where to start?'; text = 'Answer three quick questions and we will point you to a matching collection.'; result_text = 'Your starting routine: Cleanse, Treat, Moisturise'; result_button = 'See matching products'; result_link = '#s06'; anchor = 's08' }) (Blk @(
  @('question', [ordered]@{ question = 'What is your skin type?'; options = "Dry`nNormal`nOily`nCombination`nSensitive" }), @('question', [ordered]@{ question = 'What would you like to focus on?'; options = "Dryness`nDullness`nBreakouts`nTexture" }), @('question', [ordered]@{ question = 'How many steps do you want?'; options = "1 to 2 steps`n3 to 4 steps" }) ))
$S['look'] = Sec 'shop-the-look' ([ordered]@{ heading = 'Shop the look'; text = 'Everyday makeup, with the products used.'; anchor = 's09' }) (Blk @( @('pin', [ordered]@{ product = 'foundation'; x = 40; y = 24 }), @('pin', [ordered]@{ product = 'blush'; x = 58; y = 48 }), @('pin', [ordered]@{ product = 'lip-colour'; x = 34; y = 70 }) ))
$S['ingredients'] = Sec 'ingredient-spotlight' ([ordered]@{ heading = 'What is inside'; lead = 'Key ingredients and where they come from.'; free_from_label = 'Free from:'; free_from = "Item 1`nItem 2`nItem 3`nItem 4"; source_line = 'Source line: where the key ingredients come from (merchant to provide).'; anchor = 's10' }) (Blk @( @('ingredient', [ordered]@{ name = 'Ingredient name 1'; text = 'One line on what it is and why it is used. Merchant to provide; no claims without evidence.'; tone = 't4' }), @('ingredient', [ordered]@{ name = 'Ingredient name 2'; text = 'One line on what it is and why it is used. Merchant to provide; no claims without evidence.'; tone = '' }), @('ingredient', [ordered]@{ name = 'Ingredient name 3'; text = 'One line on what it is and why it is used. Merchant to provide; no claims without evidence.'; tone = 't2' }), @('ingredient', [ordered]@{ name = 'Ingredient name 4'; text = 'One line on what it is and why it is used. Merchant to provide; no claims without evidence.'; tone = 't3' }) ))
$S['ritual'] = Sec 'ritual-steps' ([ordered]@{ eyebrow = 'Your daily ritual'; heading = 'A simple ritual, step by step'; text = 'Four steps, in order, each with the product it uses.'; note = 'Optional closing tip, from the product labels.'; anchor = 's11' }) (Blk @(
  @('step', [ordered]@{ name = 'Cleanse'; text = 'How to apply, from the Face Cleanser label.'; tip = 'from the label'; time = 'from the label'; product_label = 'Face Cleanser'; product_link = '#s06' }),
  @('step', [ordered]@{ name = 'Treat'; text = 'How to apply, from the Face Serum label.'; tip = 'from the label'; time = 'from the label'; product_label = 'Face Serum'; product_link = '#s06' }),
  @('step', [ordered]@{ name = 'Moisturise'; text = 'How to apply, from the Moisturiser label.'; tip = 'from the label'; time = 'from the label'; product_label = 'Moisturiser'; product_link = '#s06' }),
  @('step', [ordered]@{ name = 'Protect'; text = 'How to apply, from the Sunscreen label.'; tip = 'from the label'; time = 'from the label'; product_label = 'Sunscreen'; product_link = '#s06' }) ))
$S['video'] = Sec 'video-section' ([ordered]@{ duration = '2:00'; eyebrow = 'Tutorial'; heading = 'Watch: building a simple routine'; text = 'A short tutorial that shows the steps in order.'; button_label = 'Shop the products'; button_link = '#s06'; anchor = 's12' }) $null
$S['compare'] = Sec 'before-after' ([ordered]@{ before_label = 'Before'; after_label = 'After'; start = 50; anchor = 's13' }) $null
$S['testimonials'] = Sec 'testimonials' ([ordered]@{ heading = 'What customers say'; rating = 5; anchor = 's14' }) (Blk @(
  @('review', [ordered]@{ quote = 'Easy to find what I needed, and it arrived quickly.'; name = 'Customer name'; product_label = 'Face Cleanser'; product_link = '#' }),
  @('review', [ordered]@{ quote = 'The packaging felt thoughtful.'; name = 'Customer name'; product_label = 'Moisturiser'; product_link = '#' }),
  @('review', [ordered]@{ quote = 'A good range for building a routine.'; name = 'Customer name'; product_label = 'Face Serum'; product_link = '#' }),
  @('review', [ordered]@{ quote = 'Clear directions and a lovely texture.'; name = 'Customer name'; product_label = 'Daily Sunscreen'; product_link = '#' }),
  @('review', [ordered]@{ quote = 'Simple to follow, and I kept using it.'; name = 'Customer name'; product_label = 'Eye Cream'; product_link = '#' }),
  @('review', [ordered]@{ quote = 'Exactly what I was looking for.'; name = 'Customer name'; product_label = 'Lip Balm'; product_link = '#' }) ))
$S['gallery'] = Sec 'customer-gallery' ([ordered]@{ heading = 'Customer photos'; lead = 'Photos from customers, uploaded by the merchant.'; anchor = 's15' }) (Blk @( @('photo', [ordered]@{ size = 'large'; tone = 't3' }), @('photo', [ordered]@{ tone = 't4' }), @('photo', [ordered]@{ tone = '' }), @('photo', [ordered]@{ tone = 't2' }), @('photo', [ordered]@{ tone = 't3' }), @('photo', [ordered]@{ size = 'wide'; tone = 't4' }) ))
$lg = @(); foreach ($x in @(@('Certification', 'verify the certificate', 'Certification logo'), @('Certification', 'verify the certificate', 'Certification logo'), @('Certification', 'verify the certificate', 'Certification logo'), @('Award', 'view the award', 'Award logo'), @('Award', 'view the award', 'Award logo'), @('Press', 'read the article', 'Publication logo'), @('Press', 'read the article', 'Publication logo'), @('Press', 'read the article', 'Publication logo'))) { $n = $lg.Count + 1; $lg += , @('logo', [ordered]@{ label = $x[2]; tag = $x[0]; aria_label = "$($x[0]) $n (placeholder): $($x[1])"; link = '#s16' }) }
$S['logos'] = Sec 'logo-list' ([ordered]@{ label = 'As recognised by'; region_label = 'Certifications, awards and press'; anchor = 's16' }) (Blk $lg)
$S['promo'] = Sec 'promo-banner' ([ordered]@{ eyebrow = 'Gift sets'; heading = 'Gift sets for every routine'; text = 'Real offer details and dates go here.'; button_label = 'Shop gift sets'; button_link = '#'; anchor = 's17' }) $null
$S['custom'] = Sec 'custom-liquid' ([ordered]@{ anchor = 's18' }) $null
$S['newsletter'] = Sec 'newsletter' ([ordered]@{ eyebrow = 'Stay in touch'; heading = 'Join the list'; text = 'Launches, offers and routine tips by email.'; button_label = 'Subscribe'; legal = 'By subscribing you agree to receive emails. Unsubscribe at any time.'; anchor = 's19' }) (Blk @( @('perk', [ordered]@{ text = 'New launches first' }), @('perk', [ordered]@{ text = 'Routine tips' }), @('perk', [ordered]@{ text = 'Offers by email' }) ))
$idx = [ordered]@{ sections = $S; order = @($S.Keys) }
[IO.File]::WriteAllText((Join-Path $T 'templates\index.json'), ($idx | ConvertTo-Json -Depth 12), $utf8)
"templates/index.json: $(@($S.Keys).Count) sections: $($S.Keys -join ', ')"